package java.util;
/** A red-black tree ordered by key. */
public class TreeMap<K,V> extends AbstractMap<K,V> implements Cloneable,java.io.Serializable {
 private static final boolean RED=false,BLACK=true;
 private static final class Node<K,V> implements Map.Entry<K,V> {K key;V value;Node<K,V> left,right,parent;boolean color=BLACK;Node(K k,V v,Node<K,V> p){key=k;value=v;parent=p;}public K getKey(){return key;}public V getValue(){return value;}public V setValue(V v){V old=value;value=v;return old;}public boolean equals(Object o){if(!(o instanceof Map.Entry))return false;Map.Entry<?,?> e=(Map.Entry<?,?>)o;return Objects.equals(key,e.getKey())&&Objects.equals(value,e.getValue());}public int hashCode(){return Objects.hashCode(key)^Objects.hashCode(value);}public String toString(){return key+"="+value;}}
 private Node<K,V> root;private int size,modCount;private final Comparator<? super K> comparator;
 public TreeMap(){this((Comparator<? super K>)null);}public TreeMap(Comparator<? super K> c){comparator=c;}public TreeMap(Map<? extends K,? extends V> m){this();putAll(m);}
 private int compare(Object a,K b){return comparator==null?((Comparable<? super K>)a).compareTo(b):comparator.compare((K)a,b);}
 private Node<K,V> find(Object k){if(k==null&&comparator==null)throw new NullPointerException();Node<K,V> p=root;while(p!=null){int c=compare(k,p.key);if(c==0)return p;p=c<0?p.left:p.right;}return null;}
 public int size(){return size;}public boolean containsKey(Object k){return find(k)!=null;}public V get(Object k){Node<K,V> p=find(k);return p==null?null:p.value;}public Comparator<? super K> comparator(){return comparator;}
 public V put(K k,V v){if(root==null){compare(k,k);root=new Node<K,V>(k,v,null);size=1;modCount++;return null;}Node<K,V> p=root,parent;int c;do{parent=p;c=compare(k,p.key);if(c<0)p=p.left;else if(c>0)p=p.right;else return p.setValue(v);}while(p!=null);Node<K,V> n=new Node<K,V>(k,v,parent);if(c<0)parent.left=n;else parent.right=n;fixInsertion(n);size++;modCount++;return null;}
 public V remove(Object k){Node<K,V> p=find(k);if(p==null)return null;V old=p.value;delete(p);return old;}public void clear(){if(size>0){root=null;size=0;modCount++;}}
 private Node<K,V> first(){Node<K,V> p=root;if(p!=null)while(p.left!=null)p=p.left;return p;}private Node<K,V> last(){Node<K,V> p=root;if(p!=null)while(p.right!=null)p=p.right;return p;}
 public K firstKey(){Node<K,V> p=first();if(p==null)throw new NoSuchElementException();return p.key;}public K lastKey(){Node<K,V> p=last();if(p==null)throw new NoSuchElementException();return p.key;}
 private Node<K,V> successor(Node<K,V> p){if(p.right!=null){p=p.right;while(p.left!=null)p=p.left;return p;}Node<K,V> x=p.parent;while(x!=null&&p==x.right){p=x;x=x.parent;}return x;}
 private static <K,V> boolean color(Node<K,V> p){return p==null?BLACK:p.color;}private static <K,V> Node<K,V> parent(Node<K,V> p){return p==null?null:p.parent;}private static <K,V> Node<K,V> left(Node<K,V> p){return p==null?null:p.left;}private static <K,V> Node<K,V> right(Node<K,V> p){return p==null?null:p.right;}private static <K,V> void color(Node<K,V> p,boolean c){if(p!=null)p.color=c;}
 private void rotateLeft(Node<K,V> p){if(p==null)return;Node<K,V> r=p.right;p.right=r.left;if(r.left!=null)r.left.parent=p;r.parent=p.parent;if(p.parent==null)root=r;else if(p==p.parent.left)p.parent.left=r;else p.parent.right=r;r.left=p;p.parent=r;}
 private void rotateRight(Node<K,V> p){if(p==null)return;Node<K,V> l=p.left;p.left=l.right;if(l.right!=null)l.right.parent=p;l.parent=p.parent;if(p.parent==null)root=l;else if(p==p.parent.right)p.parent.right=l;else p.parent.left=l;l.right=p;p.parent=l;}
 private void fixInsertion(Node<K,V> x){x.color=RED;while(x!=null&&x!=root&&color(parent(x))==RED){if(parent(x)==left(parent(parent(x)))){Node<K,V> y=right(parent(parent(x)));if(color(y)==RED){color(parent(x),BLACK);color(y,BLACK);color(parent(parent(x)),RED);x=parent(parent(x));}else{if(x==right(parent(x))){x=parent(x);rotateLeft(x);}color(parent(x),BLACK);color(parent(parent(x)),RED);rotateRight(parent(parent(x)));}}else{Node<K,V> y=left(parent(parent(x)));if(color(y)==RED){color(parent(x),BLACK);color(y,BLACK);color(parent(parent(x)),RED);x=parent(parent(x));}else{if(x==left(parent(x))){x=parent(x);rotateRight(x);}color(parent(x),BLACK);color(parent(parent(x)),RED);rotateLeft(parent(parent(x)));}}}root.color=BLACK;}
 private void delete(Node<K,V> p){modCount++;size--;if(p.left!=null&&p.right!=null){Node<K,V> s=successor(p);p.key=s.key;p.value=s.value;p=s;}Node<K,V> replacement=p.left!=null?p.left:p.right;if(replacement!=null){replacement.parent=p.parent;if(p.parent==null)root=replacement;else if(p==p.parent.left)p.parent.left=replacement;else p.parent.right=replacement;p.left=p.right=p.parent=null;if(p.color==BLACK)fixDeletion(replacement);}else if(p.parent==null)root=null;else{if(p.color==BLACK)fixDeletion(p);if(p.parent!=null){if(p==p.parent.left)p.parent.left=null;else if(p==p.parent.right)p.parent.right=null;p.parent=null;}}}
 private void fixDeletion(Node<K,V> x){while(x!=root&&color(x)==BLACK){if(x==left(parent(x))){Node<K,V> s=right(parent(x));if(color(s)==RED){color(s,BLACK);color(parent(x),RED);rotateLeft(parent(x));s=right(parent(x));}if(color(left(s))==BLACK&&color(right(s))==BLACK){color(s,RED);x=parent(x);}else{if(color(right(s))==BLACK){color(left(s),BLACK);color(s,RED);rotateRight(s);s=right(parent(x));}color(s,color(parent(x)));color(parent(x),BLACK);color(right(s),BLACK);rotateLeft(parent(x));x=root;}}else{Node<K,V> s=left(parent(x));if(color(s)==RED){color(s,BLACK);color(parent(x),RED);rotateRight(parent(x));s=left(parent(x));}if(color(right(s))==BLACK&&color(left(s))==BLACK){color(s,RED);x=parent(x);}else{if(color(left(s))==BLACK){color(right(s),BLACK);color(s,RED);rotateLeft(s);s=left(parent(x));}color(s,color(parent(x)));color(parent(x),BLACK);color(left(s),BLACK);rotateRight(parent(x));x=root;}}}color(x,BLACK);}
 public Set<Map.Entry<K,V>> entrySet(){return new AbstractSet<Map.Entry<K,V>>(){public int size(){return size;}public void clear(){TreeMap.this.clear();}public Iterator<Map.Entry<K,V>> iterator(){return new Iterator<Map.Entry<K,V>>(){Node<K,V> next=first(),last;int expected=modCount;public boolean hasNext(){return next!=null;}public Map.Entry<K,V> next(){if(expected!=modCount)throw new ConcurrentModificationException();if(next==null)throw new NoSuchElementException();last=next;next=successor(next);return last;}public void remove(){if(expected!=modCount)throw new ConcurrentModificationException();if(last==null)throw new IllegalStateException();if(last.left!=null&&last.right!=null)next=last;delete(last);last=null;expected=modCount;}};}};}
}
